const I = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name]||paths.dots}"/></svg>`;
const btn = (text, icon='', cls='') => `<button class="btn ${cls}">${icon?I(icon):''}<span>${text}</span></button>`;
const badge = (t,cls='') => `<span class="badge ${cls}">${t}</span>`;
const toggle = (on=true) => `<span class="toggle ${on?'on':''}"><i></i></span>`;
const line = (title,sub='',right='') => `<div class="setting-row"><div><strong>${title}</strong>${sub?`<p>${sub}</p>`:''}</div><div class="row-actions">${right}</div></div>`;
const notice = (text, tone='blue', sub='') => `<div class="notice ${tone}">${I(tone==='amber'?'warning':tone==='green'?'check':'info')}<div><strong>${text}</strong>${sub?`<p>${sub}</p>`:''}</div></div>`;
const input = (label,val='',opts={}) => `<div class="field"><label>${label}${opts.req?'<small>必填</small>':''}</label><div class="input ${opts.placeholder?'placeholder':''}">${val||'请输入'}${opts.select?I('down'):opts.edit?I('pencil'):''}</div>${opts.help?`<p class="hint">${opts.help}</p>`:''}</div>`;
const segmented = (label,items,active=0) => `<div class="segment-row"><label>${label}</label><div class="segments">${items.map((t,i)=>`<span class="${i===active?'selected':''}">${t}</span>`).join('')}</div></div>`;
const head = (title,sub,actions='',eyebrow='') => `<div class="page-head"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1><p>${sub}</p></div><div class="row-actions">${actions}</div></div>`;
const cardhead = (title,sub='',right='') => `<div class="card-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`;
const slot = (size='large',state='') => `<div class="mascot ${size} ${state}"><div class="orbit one"></div><div class="orbit two"></div><span class="corner tl"></span><span class="corner tr"></span><span class="corner bl"></span><span class="corner br"></span><div class="slot-content"><span class="slot-mark">${I('sparkle')}</span><strong>小纸互动区</strong><span>角色素材预留位置</span></div><div class="slot-ground"></div></div>`;
const wave = (active=false) => `<div class="wave ${active?'active':''}">${Array.from({length:35},(_,i)=>`<i style="height:${active?10+Math.round(Math.abs(Math.sin(i*1.37))*27):4}px"></i>`).join('')}</div>`;
