function doc(body,title){let special=title.startsWith('12-')?'.main>.two-col>.card .record{padding:9px 13px!important}.main>.two-col>.card .record .record-top{margin-bottom:3px!important}.main>.two-col>.card .record .hint{font-size:10px!important;line-height:1.5!important}.main>.two-col>.card .record .badge{font-size:9px;padding:2px 8px}.main>.two-col>.card .payload{font-size:10px;line-height:1.5}.main>.two-col>.card .card-head{margin-bottom:11px}.main>.two-col>.card>.hint{font-size:10px;line-height:1.5}':'';if(title.startsWith('41-'))special+='.profile-form .field{margin-bottom:10px}.profile-form .card-head{margin-bottom:16px}.profile-form .segment-row{margin-bottom:10px}.profile-form .input{height:39px}.profile-form .input.multiline{height:51px}.profile-form .setting-row{padding:10px 0}.profile-card{min-height:660px}';return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title><style>${css}${special}</style></head><body>${body}</body></html>`;}
async function main(){
 const browser=await chromium.launch({...(process.env.DESIGN_BROWSER_PATH?{executablePath:process.env.DESIGN_BROWSER_PATH}:{}),headless:true,args:['--disable-gpu','--disable-background-networking','--no-first-run']});
 const context=await browser.newContext({viewport:{width:1600,height:1000},deviceScaleFactor:1.2,locale:'zh-CN',offline:true});
 const page=await context.newPage();
 const errors=[]; page.on('pageerror',err=>errors.push(String(err)));
 const manifest=[];
 const only=process.argv[2];
 const previous=only?JSON.parse(fs.readFileSync(path.join(root,'manifest.json'),'utf8')).pages:[];
 for(const [name,category,render] of pages){
  if(only&&!name.startsWith(only)){const prior=previous.find(p=>p.name===name);if(!prior)throw new Error('缺少已验证页面：'+name);manifest.push(prior);continue;}
  let rendered=render();
  if (name.startsWith('02-')) rendered=rendered.replace('class="btn full soft"','class="btn full disabled"');
  if (name.startsWith('08-')) rendered=rendered.replace('老师，刹车时人为什么会向前倾？</div>', '老师，刹车时人为什么会向前倾？<div style="margin-top:7px">'+btn('停止播报','volume','ghost')+'</div></div>');
  if (name.startsWith('17-')) rendered=rendered.replace('关闭后继续听课与更新认知，只是不对外发言。</p></div><div class="row-actions">'+toggle(), '关闭后继续听课与更新认知，只是不对外发言。</p></div><div class="row-actions">'+toggle(false));
  const html=doc(rendered,name); const file=path.join(root,'html',name+'.html');fs.writeFileSync(file,html,'utf8');
  await page.goto('file:///'+file.replace(/\\/g,'/'));await page.evaluate(()=>document.fonts.ready);
  const qa=await page.evaluate(()=>{const app=document.querySelector('.app');const main=document.querySelector('.main');const bad=[...document.querySelectorAll('.main .card,.main .page-head,.main .class-layout,.main .settings-layout,.main .savebar,.main .hero,.main .home-bottom,.main .report-grid,.main .record,.main .knowledge-card,.main .empty-class,.main .stats-strip,.main .detail-tabs')].filter(e=>{const b=e.getBoundingClientRect();return b.bottom>1000.8||b.right>1600.8}).map(e=>({tag:e.className,bottom:e.getBoundingClientRect().bottom,right:e.getBoundingClientRect().right,text:e.textContent.slice(0,25)}));return {app:{width:app.clientWidth,height:app.clientHeight},bodyWidth:document.body.scrollWidth,overflow:bad,internalIDs:[...document.querySelectorAll('.main')].some(e=>/\b[tpqk]\d+\b/.test(e.innerText)),visibleText:main.innerText.length};});
  const png=path.join(root,'png',name+'.png');await page.screenshot({path:png});
  const meta=await sharp(png).metadata();
  manifest.push({name,category,png:'png/'+name+'.png',width:meta.width,height:meta.height,sha256:crypto.createHash('sha256').update(fs.readFileSync(png)).digest('hex'),qa});
  console.log(name+' '+meta.width+'x'+meta.height+(qa.overflow.length?' OVERFLOW:'+JSON.stringify(qa.overflow):' OK'));
 }
 fs.writeFileSync(path.join(root,'manifest.json'),JSON.stringify({generated:'2026-10-17 Asia/Shanghai',scope:'静态概念设计；未接入后端；未启动智能体；全为示例数据',pages:manifest,errors},null,2),'utf8');
 const galleryCSS=`*{box-sizing:border-box}body{margin:0;background:#eef4fc;font-family:"Microsoft YaHei UI","Microsoft YaHei",sans-serif;color:#213c60}header{padding:44px 50px 30px;display:flex;justify-content:space-between;align-items:end}h1{font-size:30px;margin:0 0 8px}p{font-size:13px;color:#8a9eb9;margin:0}.tag{font-size:11px;color:#6a96ca;padding:8px 14px;background:#e1edfc;border-radius:20px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;padding:0 40px 34px}.item{background:white;border:1px solid #dbe6f4;border-radius:14px;overflow:hidden;box-shadow:0 4px 18px #40608004;text-decoration:none;color:inherit}.item img{width:100%;display:block;aspect-ratio:1.6}.label{padding:13px 16px;display:flex;align-items:center;justify-content:space-between;font-size:12px}.label span{font-size:10px;color:#99abc1}.foot{font-size:11px;color:#92a8c3;padding:0 45px 28px}a{text-decoration:none;color:inherit}`;
 const item=(m,prefix='')=>`<a class="item" href="${prefix}png/${m.name}.png"><img src="${prefix}png/${m.name}.png"><div class="label">${m.name.replace(/-/g,' / ')}<span>${m.category}</span></div></a>`;
 fs.writeFileSync(path.join(root,'index.html'),`<!doctype html><meta charset="utf-8"><title>讲给我听 · 全页面设计图册</title><style>${galleryCSS}.grid{grid-template-columns:repeat(3,1fr)}</style><header><div><h1>讲给我听 · 全页面设计图册</h1><p>${manifest.length} 张桌面页面与关键状态 · 点击查看原尺寸 PNG</p></div><div class="tag">蓝白 · 清楚 · 有陪伴感</div></header><div class="grid">${manifest.map(m=>item(m)).join('')}</div><div class="foot">静态设计 / 示例数据 / 吉祥物仅预留位置 / 正式前端不含上传录音和内部关联信息</div>`,'utf8');
 for(let n=0;n<Math.ceil(manifest.length/9);n++){
  const subset=manifest.slice(n*9,n*9+9);const html=`<!doctype html><meta charset="utf-8"><style>${galleryCSS}</style><header><div><h1>讲给我听 · 设计总览 ${String(n+1).padStart(2,'0')}</h1><p>${subset[0].name} — ${subset.at(-1).name}　/　静态设计 · 示例内容</p></div><div class="tag">${n*9+1}–${Math.min((n+1)*9,manifest.length)} / ${manifest.length}</div></header><div class="grid">${subset.map(m=>item(m,'../')).join('')}</div><div class="foot">正式前端覆盖既有功能，移除上传录音与内部关联展示；原调试前端保留。所有角色位置等待正式素材。</div>`;
  const file=path.join(root,'overview','总览-'+(n+1)+'.html');fs.writeFileSync(file,html,'utf8');await page.setViewportSize({width:1600,height:1200});await page.goto('file:///'+file.replace(/\\/g,'/'));await page.evaluate(()=>document.fonts.ready);await page.screenshot({path:path.join(root,'overview','总览-'+(n+1)+'.png'),fullPage:true});
 }
 await browser.close();
 console.log('TOTAL '+manifest.length+'; errors '+errors.length+'; overflow pages '+manifest.filter(m=>m.qa.overflow.length).length);
}
main().catch(e=>{console.error(e);process.exit(1)});
